const response = $input.first().json;

try {
  const content = response.choices[0].message.content;

  // Try to parse as JSON
  let parsed;
  try {
    parsed = JSON.parse(content);
  } catch (e) {
    // If not valid JSON, try to extract JSON from the response
    const jsonMatch = content.match(/\{[\s\S]*\}/);
    if (jsonMatch) {
      parsed = JSON.parse(jsonMatch[0]);
    } else {
      parsed = {
        reply: content,
        intent: 'unknown',
        action: null
      };
    }
  }

  return [{
    json: {
      reply: parsed.reply || 'Lo siento, no pude procesar tu mensaje.',
      intent: parsed.intent || 'unknown',
      action: parsed.action || null
    }
  }];
} catch (error) {
  return [{
    json: {
      reply: 'Lo siento, hubo un error al procesar tu mensaje. Por favor, intenta de nuevo o contacta a un agente.',
      intent: 'error',
      action: null
    }
  }];
}
